class Node {
  constructor() {
    this.max = 0;
    this.argMax = 0;
    this.lazy = 0;
    this.left = null;
    this.right = null;
  }
}

function rangeAdd(node, L, R, ql, qr, delta) {
  if (qr < L || R < ql) return;
  if (ql <= L && R <= qr) {
    node.max += delta;
    node.lazy += delta;
    return;
  }
  push(node);
  const mid = (L + R) >>> 1;
  rangeAdd(node.left, L, mid, ql, qr, delta);
  rangeAdd(node.right, mid + 1, R, ql, qr, delta);
  pull(node);
}
